#!/usr/bin/env python3
from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

def read(path: str) -> str:
    return (ROOT / path).read_text(encoding='utf-8')

def write(path: str, content: str) -> None:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding='utf-8')

def replace_once(path: str, before: str, after: str) -> None:
    source = read(path)
    count = source.count(before)
    if count != 1:
        raise SystemExit(f'{path}: expected one replacement anchor, found {count}')
    write(path, source.replace(before, after))

write('codex-rs/hepta-contracts/src/quota_registry.rs', '//! Canonical six-dimensional quota registry for AuthBus.\n//!\n//! This module owns field order, external names, projection keys and migration\n//! policy. Legacy five-dimensional vectors remain compatibility projections;\n//! they cannot supply or discard `request_count` without an explicit policy.\n\nuse std::collections::BTreeMap;\nuse std::collections::BTreeSet;\n\nuse serde::Deserialize;\nuse serde::Serialize;\n\nuse crate::Sha256Digest;\n\n/// Stable schema name for the first canonical AuthBus quota registry.\npub const AUTHBUS_QUOTA_REGISTRY_SCHEMA: &str = "hepta.authbus.quota-registry.v1";\n/// Stable integer version for the first canonical AuthBus quota registry.\npub const AUTHBUS_QUOTA_REGISTRY_VERSION: u32 = 1;\n/// Number of dimensions in the canonical AuthBus quota vector.\npub const AUTHBUS_QUOTA_DIMENSION_COUNT: usize = 6;\n/// Digest of the committed descriptor registry, using the encoding implemented\n/// by [`authbus_quota_registry_digest`].\npub const AUTHBUS_QUOTA_REGISTRY_SHA256: &str =\n    "f6702be58c499d853d273f3174a2556481a3f5b4284cd9cd0b0a247160d7ac08";\n\n/// Stable quota dimension identifier.\n#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]\n#[repr(u8)]\npub enum QuotaDimension {\n    /// Number of admitted requests.\n    RequestCount = 0,\n    /// Requests per minute.\n    Rpm = 1,\n    /// Tokens per minute.\n    Tpm = 2,\n    /// Concurrent in-flight requests.\n    Concurrency = 3,\n    /// Provider or owner budget consumed in a day.\n    DayBudget = 4,\n    /// Context tokens reserved or consumed.\n    Context = 5,\n}\n\nimpl QuotaDimension {\n    /// Canonical dimension order. This order is part of the schema digest.\n    pub const ALL: [Self; AUTHBUS_QUOTA_DIMENSION_COUNT] = [\n        Self::RequestCount,\n        Self::Rpm,\n        Self::Tpm,\n        Self::Concurrency,\n        Self::DayBudget,\n        Self::Context,\n    ];\n\n    /// Return this dimension\'s stable descriptor.\n    pub const fn descriptor(self) -> &\'static QuotaDimensionDescriptor {\n        &AUTHBUS_QUOTA_DIMENSIONS[self as usize]\n    }\n}\n\n/// Unit carried by a quota dimension.\n#[derive(Clone, Copy, Debug, Eq, PartialEq)]\npub enum QuotaUnit {\n    /// Absolute request count.\n    Requests,\n    /// Requests per minute.\n    RequestsPerMinute,\n    /// Tokens per minute.\n    TokensPerMinute,\n    /// Concurrent request count.\n    ConcurrentRequests,\n    /// Abstract provider or owner budget units per day.\n    BudgetUnitsPerDay,\n    /// Token count.\n    Tokens,\n}\n\nimpl QuotaUnit {\n    /// Stable unit name included in the registry digest.\n    pub const fn as_str(self) -> &\'static str {\n        match self {\n            Self::Requests => "requests",\n            Self::RequestsPerMinute => "requests_per_minute",\n            Self::TokensPerMinute => "tokens_per_minute",\n            Self::ConcurrentRequests => "concurrent_requests",\n            Self::BudgetUnitsPerDay => "budget_units_per_day",\n            Self::Tokens => "tokens",\n        }\n    }\n}\n\n/// One canonical descriptor. Every wire, SQLite, receipt and metric name is\n/// declared here rather than duplicated by individual AuthBus tranches.\n#[derive(Clone, Copy, Debug, Eq, PartialEq)]\npub struct QuotaDimensionDescriptor {\n    /// Stable dimension identifier.\n    pub dimension: QuotaDimension,\n    /// Zero-based canonical order.\n    pub ordinal: u8,\n    /// Canonical internal key.\n    pub canonical_key: &\'static str,\n    /// Versioned wire key.\n    pub wire_key: &\'static str,\n    /// SQLite column used for a configured limit.\n    pub sqlite_limit_column: &\'static str,\n    /// SQLite column used for a held reservation.\n    pub sqlite_reserved_column: &\'static str,\n    /// SQLite column used for terminal or accumulated usage.\n    pub sqlite_used_column: &\'static str,\n    /// Key emitted into durable receipts.\n    pub receipt_key: &\'static str,\n    /// Stable metrics suffix.\n    pub metric_key: &\'static str,\n    /// Semantic unit.\n    pub unit: QuotaUnit,\n    /// Whether the five-dimensional v0 projection carried this dimension.\n    pub present_in_legacy_v0: bool,\n}\n\n/// The only AuthBus quota field registry.\npub const AUTHBUS_QUOTA_DIMENSIONS: [QuotaDimensionDescriptor; AUTHBUS_QUOTA_DIMENSION_COUNT] = [\n    QuotaDimensionDescriptor {\n        dimension: QuotaDimension::RequestCount,\n        ordinal: 0,\n        canonical_key: "request_count",\n        wire_key: "request_count",\n        sqlite_limit_column: "limit_request_count",\n        sqlite_reserved_column: "reserved_request_count",\n        sqlite_used_column: "used_request_count",\n        receipt_key: "request_count",\n        metric_key: "quota_request_count",\n        unit: QuotaUnit::Requests,\n        present_in_legacy_v0: false,\n    },\n    QuotaDimensionDescriptor {\n        dimension: QuotaDimension::Rpm,\n        ordinal: 1,\n        canonical_key: "rpm",\n        wire_key: "rpm",\n        sqlite_limit_column: "limit_rpm",\n        sqlite_reserved_column: "reserved_rpm",\n        sqlite_used_column: "used_rpm",\n        receipt_key: "rpm",\n        metric_key: "quota_rpm",\n        unit: QuotaUnit::RequestsPerMinute,\n        present_in_legacy_v0: true,\n    },\n    QuotaDimensionDescriptor {\n        dimension: QuotaDimension::Tpm,\n        ordinal: 2,\n        canonical_key: "tpm",\n        wire_key: "tpm",\n        sqlite_limit_column: "limit_tpm",\n        sqlite_reserved_column: "reserved_tpm",\n        sqlite_used_column: "used_tpm",\n        receipt_key: "tpm",\n        metric_key: "quota_tpm",\n        unit: QuotaUnit::TokensPerMinute,\n        present_in_legacy_v0: true,\n    },\n    QuotaDimensionDescriptor {\n        dimension: QuotaDimension::Concurrency,\n        ordinal: 3,\n        canonical_key: "concurrency",\n        wire_key: "concurrency",\n        sqlite_limit_column: "limit_concurrency",\n        sqlite_reserved_column: "reserved_concurrency",\n        sqlite_used_column: "used_concurrency",\n        receipt_key: "concurrency",\n        metric_key: "quota_concurrency",\n        unit: QuotaUnit::ConcurrentRequests,\n        present_in_legacy_v0: true,\n    },\n    QuotaDimensionDescriptor {\n        dimension: QuotaDimension::DayBudget,\n        ordinal: 4,\n        canonical_key: "day_budget",\n        wire_key: "day_budget",\n        sqlite_limit_column: "limit_day_budget",\n        sqlite_reserved_column: "reserved_day_budget",\n        sqlite_used_column: "used_day_budget",\n        receipt_key: "day_budget",\n        metric_key: "quota_day_budget",\n        unit: QuotaUnit::BudgetUnitsPerDay,\n        present_in_legacy_v0: true,\n    },\n    QuotaDimensionDescriptor {\n        dimension: QuotaDimension::Context,\n        ordinal: 5,\n        canonical_key: "context",\n        wire_key: "context",\n        sqlite_limit_column: "limit_context",\n        sqlite_reserved_column: "reserved_context",\n        sqlite_used_column: "used_context",\n        receipt_key: "context",\n        metric_key: "quota_context",\n        unit: QuotaUnit::Tokens,\n        present_in_legacy_v0: true,\n    },\n];\n\n/// Projection surface selected from the canonical descriptor registry.\n#[derive(Clone, Copy, Debug, Eq, PartialEq)]\npub enum QuotaProjection {\n    /// Versioned wire field names.\n    Wire,\n    /// SQLite configured-limit columns.\n    SqliteLimit,\n    /// SQLite held-reservation columns.\n    SqliteReserved,\n    /// SQLite terminal/accumulated-use columns.\n    SqliteUsed,\n    /// Durable receipt keys.\n    Receipt,\n    /// Stable metric suffixes.\n    Metric,\n}\n\nimpl QuotaDimensionDescriptor {\n    /// Return the field name for one projection surface.\n    pub const fn projection_key(self, projection: QuotaProjection) -> &\'static str {\n        match projection {\n            QuotaProjection::Wire => self.wire_key,\n            QuotaProjection::SqliteLimit => self.sqlite_limit_column,\n            QuotaProjection::SqliteReserved => self.sqlite_reserved_column,\n            QuotaProjection::SqliteUsed => self.sqlite_used_column,\n            QuotaProjection::Receipt => self.receipt_key,\n            QuotaProjection::Metric => self.metric_key,\n        }\n    }\n}\n\n/// Registry validation error.\n#[derive(Clone, Copy, Debug, Eq, PartialEq)]\npub enum QuotaRegistryError {\n    /// Registry length differs from the schema constant.\n    InvalidDimensionCount,\n    /// Descriptor ordinal or enum value differs from its array position.\n    InvalidOrdinal,\n    /// At least one projection contains a duplicate key.\n    DuplicateProjectionKey,\n}\n\n/// Validate descriptor order and key uniqueness.\npub fn validate_authbus_quota_registry() -> Result<(), QuotaRegistryError> {\n    if AUTHBUS_QUOTA_DIMENSIONS.len() != AUTHBUS_QUOTA_DIMENSION_COUNT {\n        return Err(QuotaRegistryError::InvalidDimensionCount);\n    }\n\n    for (index, descriptor) in AUTHBUS_QUOTA_DIMENSIONS.iter().enumerate() {\n        if usize::from(descriptor.ordinal) != index || descriptor.dimension as usize != index {\n            return Err(QuotaRegistryError::InvalidOrdinal);\n        }\n    }\n\n    for projection in [\n        QuotaProjection::Wire,\n        QuotaProjection::SqliteLimit,\n        QuotaProjection::SqliteReserved,\n        QuotaProjection::SqliteUsed,\n        QuotaProjection::Receipt,\n        QuotaProjection::Metric,\n    ] {\n        let mut keys = BTreeSet::new();\n        if !AUTHBUS_QUOTA_DIMENSIONS\n            .iter()\n            .all(|descriptor| keys.insert(descriptor.projection_key(projection)))\n        {\n            return Err(QuotaRegistryError::DuplicateProjectionKey);\n        }\n    }\n\n    Ok(())\n}\n\n/// Compute the digest that binds field order, names, units and legacy presence.\npub fn authbus_quota_registry_digest() -> Sha256Digest {\n    let mut bytes = Vec::new();\n    push_text(&mut bytes, AUTHBUS_QUOTA_REGISTRY_SCHEMA);\n    bytes.extend_from_slice(&AUTHBUS_QUOTA_REGISTRY_VERSION.to_be_bytes());\n    for descriptor in AUTHBUS_QUOTA_DIMENSIONS {\n        bytes.push(descriptor.ordinal);\n        push_text(&mut bytes, descriptor.canonical_key);\n        push_text(&mut bytes, descriptor.wire_key);\n        push_text(&mut bytes, descriptor.sqlite_limit_column);\n        push_text(&mut bytes, descriptor.sqlite_reserved_column);\n        push_text(&mut bytes, descriptor.sqlite_used_column);\n        push_text(&mut bytes, descriptor.receipt_key);\n        push_text(&mut bytes, descriptor.metric_key);\n        push_text(&mut bytes, descriptor.unit.as_str());\n        bytes.push(u8::from(descriptor.present_in_legacy_v0));\n    }\n    Sha256Digest::for_bytes(&bytes)\n}\n\n/// Explicit policy required when a legacy vector has no request-count field.\n#[derive(Clone, Copy, Debug, Eq, PartialEq)]\npub enum LegacyRequestCountPolicy {\n    /// Reject the vector because request count is unknown.\n    RejectMissing,\n    /// Interpret one legacy reservation as exactly one admitted request.\n    AssumeOnePerPermit,\n}\n\n/// Error returned by a compatibility projection.\n#[derive(Clone, Copy, Debug, Eq, PartialEq)]\npub enum QuotaProjectionError {\n    /// A legacy vector omitted request count and no assumption was authorized.\n    MissingRequestCount,\n    /// A six-dimensional vector cannot be represented by the legacy shape.\n    LossyLegacyDowngrade {\n        /// Request count that would be discarded.\n        request_count: u64,\n    },\n}\n\n/// Explicit five-dimensional compatibility value. It is not schema authority.\n#[derive(Clone, Copy, Debug, Default, Eq, PartialEq, Serialize, Deserialize)]\npub struct LegacyQuotaVectorV0 {\n    /// Requests per minute.\n    pub rpm: u64,\n    /// Tokens per minute.\n    pub tpm: u64,\n    /// Concurrent in-flight requests.\n    pub concurrency: u64,\n    /// Provider or owner daily budget.\n    pub day_budget: u64,\n    /// Context token count.\n    pub context: u64,\n}\n\n/// Canonical six-dimensional quota value.\n#[derive(Clone, Copy, Debug, Default, Eq, PartialEq, Serialize, Deserialize)]\npub struct CanonicalQuotaVector {\n    /// Number of admitted requests.\n    pub request_count: u64,\n    /// Requests per minute.\n    pub rpm: u64,\n    /// Tokens per minute.\n    pub tpm: u64,\n    /// Concurrent in-flight requests.\n    pub concurrency: u64,\n    /// Provider or owner daily budget.\n    pub day_budget: u64,\n    /// Context token count.\n    pub context: u64,\n}\n\nimpl CanonicalQuotaVector {\n    /// Construct a complete six-dimensional vector.\n    pub const fn new(\n        request_count: u64,\n        rpm: u64,\n        tpm: u64,\n        concurrency: u64,\n        day_budget: u64,\n        context: u64,\n    ) -> Self {\n        Self {\n            request_count,\n            rpm,\n            tpm,\n            concurrency,\n            day_budget,\n            context,\n        }\n    }\n\n    /// Upgrade a legacy five-dimensional vector under an explicit policy.\n    pub fn from_legacy(\n        value: LegacyQuotaVectorV0,\n        policy: LegacyRequestCountPolicy,\n    ) -> Result<Self, QuotaProjectionError> {\n        let request_count = match policy {\n            LegacyRequestCountPolicy::RejectMissing => {\n                return Err(QuotaProjectionError::MissingRequestCount);\n            }\n            LegacyRequestCountPolicy::AssumeOnePerPermit => 1,\n        };\n        Ok(Self::new(\n            request_count,\n            value.rpm,\n            value.tpm,\n            value.concurrency,\n            value.day_budget,\n            value.context,\n        ))\n    }\n\n    /// Upgrade legacy dimensions under an explicit request-count policy.\n    pub fn from_legacy_dimensions(\n        rpm: u64,\n        tpm: u64,\n        concurrency: u64,\n        day_budget: u64,\n        context: u64,\n        policy: LegacyRequestCountPolicy,\n    ) -> Result<Self, QuotaProjectionError> {\n        Self::from_legacy(\n            LegacyQuotaVectorV0 {\n                rpm,\n                tpm,\n                concurrency,\n                day_budget,\n                context,\n            },\n            policy,\n        )\n    }\n\n    /// Downgrade only when request count is exactly one and no information is\n    /// lost.\n    pub fn try_to_legacy(self) -> Result<LegacyQuotaVectorV0, QuotaProjectionError> {\n        if self.request_count != 1 {\n            return Err(QuotaProjectionError::LossyLegacyDowngrade {\n                request_count: self.request_count,\n            });\n        }\n        Ok(LegacyQuotaVectorV0 {\n            rpm: self.rpm,\n            tpm: self.tpm,\n            concurrency: self.concurrency,\n            day_budget: self.day_budget,\n            context: self.context,\n        })\n    }\n\n    /// Return a value by stable dimension.\n    pub const fn value(self, dimension: QuotaDimension) -> u64 {\n        match dimension {\n            QuotaDimension::RequestCount => self.request_count,\n            QuotaDimension::Rpm => self.rpm,\n            QuotaDimension::Tpm => self.tpm,\n            QuotaDimension::Concurrency => self.concurrency,\n            QuotaDimension::DayBudget => self.day_budget,\n            QuotaDimension::Context => self.context,\n        }\n    }\n\n    /// Return values in canonical registry order.\n    pub const fn values(self) -> [u64; AUTHBUS_QUOTA_DIMENSION_COUNT] {\n        [\n            self.request_count,\n            self.rpm,\n            self.tpm,\n            self.concurrency,\n            self.day_budget,\n            self.context,\n        ]\n    }\n\n    /// Whether every dimension is zero.\n    pub const fn is_zero(self) -> bool {\n        self.request_count == 0\n            && self.rpm == 0\n            && self.tpm == 0\n            && self.concurrency == 0\n            && self.day_budget == 0\n            && self.context == 0\n    }\n\n    /// Checked component-wise addition.\n    pub fn checked_add(self, other: Self) -> Option<Self> {\n        Some(Self {\n            request_count: self.request_count.checked_add(other.request_count)?,\n            rpm: self.rpm.checked_add(other.rpm)?,\n            tpm: self.tpm.checked_add(other.tpm)?,\n            concurrency: self.concurrency.checked_add(other.concurrency)?,\n            day_budget: self.day_budget.checked_add(other.day_budget)?,\n            context: self.context.checked_add(other.context)?,\n        })\n    }\n\n    /// Checked component-wise subtraction.\n    pub fn checked_sub(self, other: Self) -> Option<Self> {\n        Some(Self {\n            request_count: self.request_count.checked_sub(other.request_count)?,\n            rpm: self.rpm.checked_sub(other.rpm)?,\n            tpm: self.tpm.checked_sub(other.tpm)?,\n            concurrency: self.concurrency.checked_sub(other.concurrency)?,\n            day_budget: self.day_budget.checked_sub(other.day_budget)?,\n            context: self.context.checked_sub(other.context)?,\n        })\n    }\n\n    /// Whether every component fits within the supplied vector.\n    pub const fn fits_within(self, limit: Self) -> bool {\n        self.request_count <= limit.request_count\n            && self.rpm <= limit.rpm\n            && self.tpm <= limit.tpm\n            && self.concurrency <= limit.concurrency\n            && self.day_budget <= limit.day_budget\n            && self.context <= limit.context\n    }\n\n    /// Convert an in-flight reservation to terminal usage.\n    pub const fn terminal_usage(self) -> Self {\n        Self {\n            concurrency: 0,\n            ..self\n        }\n    }\n\n    /// Project values through one registry-owned external naming surface.\n    pub fn project(self, projection: QuotaProjection) -> BTreeMap<&\'static str, u64> {\n        AUTHBUS_QUOTA_DIMENSIONS\n            .iter()\n            .map(|descriptor| {\n                (\n                    descriptor.projection_key(projection),\n                    self.value(descriptor.dimension),\n                )\n            })\n            .collect()\n    }\n\n    /// Digest registry identity and all values in canonical order.\n    pub fn digest(self) -> Sha256Digest {\n        let mut bytes = Vec::new();\n        push_text(&mut bytes, "hepta.authbus.quota-vector.v1");\n        push_text(&mut bytes, AUTHBUS_QUOTA_REGISTRY_SHA256);\n        for value in self.values() {\n            bytes.extend_from_slice(&value.to_be_bytes());\n        }\n        Sha256Digest::for_bytes(&bytes)\n    }\n}\n\n/// Canonical six-dimensional quota limits. `None` is unknown and always\n/// denies admission.\n#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize, Deserialize)]\npub struct CanonicalQuotaLimits {\n    /// Request-count limit.\n    pub request_count: Option<u64>,\n    /// Requests-per-minute limit.\n    pub rpm: Option<u64>,\n    /// Tokens-per-minute limit.\n    pub tpm: Option<u64>,\n    /// Concurrency limit.\n    pub concurrency: Option<u64>,\n    /// Daily budget limit.\n    pub day_budget: Option<u64>,\n    /// Context-token limit.\n    pub context: Option<u64>,\n}\n\nimpl CanonicalQuotaLimits {\n    /// Construct fully known limits from a vector.\n    pub const fn known(value: CanonicalQuotaVector) -> Self {\n        Self {\n            request_count: Some(value.request_count),\n            rpm: Some(value.rpm),\n            tpm: Some(value.tpm),\n            concurrency: Some(value.concurrency),\n            day_budget: Some(value.day_budget),\n            context: Some(value.context),\n        }\n    }\n\n    /// Construct a compatibility view with unknown request count.\n    pub const fn unknown_request_count(value: CanonicalQuotaVector) -> Self {\n        Self {\n            request_count: None,\n            rpm: Some(value.rpm),\n            tpm: Some(value.tpm),\n            concurrency: Some(value.concurrency),\n            day_budget: Some(value.day_budget),\n            context: Some(value.context),\n        }\n    }\n\n    /// Whether every canonical dimension is bounded.\n    pub const fn is_fully_known(self) -> bool {\n        self.request_count.is_some()\n            && self.rpm.is_some()\n            && self.tpm.is_some()\n            && self.concurrency.is_some()\n            && self.day_budget.is_some()\n            && self.context.is_some()\n    }\n\n    /// Fail-closed admission check over used, held and requested values.\n    pub fn can_hold(\n        self,\n        used: CanonicalQuotaVector,\n        held: CanonicalQuotaVector,\n        requested: CanonicalQuotaVector,\n    ) -> bool {\n        fn dimension(limit: Option<u64>, used: u64, held: u64, requested: u64) -> bool {\n            let Some(limit) = limit else {\n                return false;\n            };\n            used.checked_add(held)\n                .and_then(|committed| committed.checked_add(requested))\n                .is_some_and(|total| total <= limit)\n        }\n\n        dimension(\n            self.request_count,\n            used.request_count,\n            held.request_count,\n            requested.request_count,\n        ) && dimension(self.rpm, used.rpm, held.rpm, requested.rpm)\n            && dimension(self.tpm, used.tpm, held.tpm, requested.tpm)\n            && dimension(\n                self.concurrency,\n                used.concurrency,\n                held.concurrency,\n                requested.concurrency,\n            )\n            && dimension(\n                self.day_budget,\n                used.day_budget,\n                held.day_budget,\n                requested.day_budget,\n            )\n            && dimension(self.context, used.context, held.context, requested.context)\n    }\n\n    /// Project optional limits through one registry-owned naming surface.\n    pub fn project(\n        self,\n        projection: QuotaProjection,\n    ) -> BTreeMap<&\'static str, Option<u64>> {\n        AUTHBUS_QUOTA_DIMENSIONS\n            .iter()\n            .map(|descriptor| {\n                let value = match descriptor.dimension {\n                    QuotaDimension::RequestCount => self.request_count,\n                    QuotaDimension::Rpm => self.rpm,\n                    QuotaDimension::Tpm => self.tpm,\n                    QuotaDimension::Concurrency => self.concurrency,\n                    QuotaDimension::DayBudget => self.day_budget,\n                    QuotaDimension::Context => self.context,\n                };\n                (descriptor.projection_key(projection), value)\n            })\n            .collect()\n    }\n}\n\n/// Evidence emitted when a legacy vector is upgraded.\n#[derive(Clone, Debug, Eq, PartialEq)]\npub struct QuotaMigrationReceipt {\n    /// Legacy schema name.\n    pub source_schema: &\'static str,\n    /// Canonical target schema name.\n    pub target_schema: &\'static str,\n    /// Whether request count was supplied by an explicit assumption.\n    pub request_count_assumed: bool,\n    /// Digest of the canonical descriptor registry.\n    pub target_registry_sha256: Sha256Digest,\n}\n\n/// Upgrade a legacy value and return a digest-bound migration receipt.\npub fn migrate_legacy_quota(\n    value: LegacyQuotaVectorV0,\n    policy: LegacyRequestCountPolicy,\n) -> Result<(CanonicalQuotaVector, QuotaMigrationReceipt), QuotaProjectionError> {\n    let canonical = CanonicalQuotaVector::from_legacy(value, policy)?;\n    Ok((\n        canonical,\n        QuotaMigrationReceipt {\n            source_schema: "hepta.authbus.quota-vector.v0",\n            target_schema: AUTHBUS_QUOTA_REGISTRY_SCHEMA,\n            request_count_assumed: matches!(\n                policy,\n                LegacyRequestCountPolicy::AssumeOnePerPermit\n            ),\n            target_registry_sha256: authbus_quota_registry_digest(),\n        },\n    ))\n}\n\nfn push_text(bytes: &mut Vec<u8>, value: &str) {\n    bytes.extend_from_slice(&(value.len() as u64).to_be_bytes());\n    bytes.extend_from_slice(value.as_bytes());\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n\n    #[test]\n    fn registry_order_projection_names_and_digest_are_stable() {\n        validate_authbus_quota_registry().expect("valid registry");\n        assert_eq!(\n            authbus_quota_registry_digest().as_str(),\n            AUTHBUS_QUOTA_REGISTRY_SHA256\n        );\n        assert_eq!(\n            QuotaDimension::ALL.map(|dimension| dimension.descriptor().canonical_key),\n            [\n                "request_count",\n                "rpm",\n                "tpm",\n                "concurrency",\n                "day_budget",\n                "context",\n            ]\n        );\n    }\n\n    #[test]\n    fn every_projection_is_registry_derived() {\n        let value = CanonicalQuotaVector::new(1, 2, 3, 4, 5, 6);\n        assert_eq!(\n            value.project(QuotaProjection::Wire),\n            BTreeMap::from([\n                ("concurrency", 4),\n                ("context", 6),\n                ("day_budget", 5),\n                ("request_count", 1),\n                ("rpm", 2),\n                ("tpm", 3),\n            ])\n        );\n        assert_eq!(\n            value.project(QuotaProjection::SqliteReserved),\n            BTreeMap::from([\n                ("reserved_concurrency", 4),\n                ("reserved_context", 6),\n                ("reserved_day_budget", 5),\n                ("reserved_request_count", 1),\n                ("reserved_rpm", 2),\n                ("reserved_tpm", 3),\n            ])\n        );\n        assert_eq!(\n            value.project(QuotaProjection::Receipt),\n            value.project(QuotaProjection::Wire)\n        );\n        assert_eq!(\n            value.project(QuotaProjection::Metric),\n            BTreeMap::from([\n                ("quota_concurrency", 4),\n                ("quota_context", 6),\n                ("quota_day_budget", 5),\n                ("quota_request_count", 1),\n                ("quota_rpm", 2),\n                ("quota_tpm", 3),\n            ])\n        );\n    }\n\n    #[test]\n    fn legacy_upgrade_and_downgrade_are_never_implicit() {\n        let legacy = LegacyQuotaVectorV0 {\n            rpm: 2,\n            tpm: 300,\n            concurrency: 1,\n            day_budget: 400,\n            context: 512,\n        };\n        assert_eq!(\n            CanonicalQuotaVector::from_legacy(\n                legacy,\n                LegacyRequestCountPolicy::RejectMissing\n            ),\n            Err(QuotaProjectionError::MissingRequestCount)\n        );\n        let canonical = CanonicalQuotaVector::from_legacy(\n            legacy,\n            LegacyRequestCountPolicy::AssumeOnePerPermit,\n        )\n        .expect("explicit migration");\n        assert_eq!(canonical.request_count, 1);\n        assert_eq!(canonical.try_to_legacy(), Ok(legacy));\n        assert_eq!(\n            CanonicalQuotaVector::new(2, 2, 300, 1, 400, 512).try_to_legacy(),\n            Err(QuotaProjectionError::LossyLegacyDowngrade { request_count: 2 })\n        );\n    }\n\n    #[test]\n    fn unknown_limit_and_overflow_fail_closed() {\n        let capacity = CanonicalQuotaVector::new(10, 10, 100, 2, 1_000, 2_000);\n        let requested = CanonicalQuotaVector::new(1, 1, 20, 1, 100, 200);\n        assert!(CanonicalQuotaLimits::known(capacity).can_hold(\n            CanonicalQuotaVector::default(),\n            CanonicalQuotaVector::default(),\n            requested\n        ));\n        assert!(!CanonicalQuotaLimits::unknown_request_count(capacity).can_hold(\n            CanonicalQuotaVector::default(),\n            CanonicalQuotaVector::default(),\n            requested\n        ));\n        assert!(\n            CanonicalQuotaVector::new(u64::MAX, 0, 0, 0, 0, 0)\n                .checked_add(CanonicalQuotaVector::new(1, 0, 0, 0, 0, 0))\n                .is_none()\n        );\n    }\n}\n')
write('codex-rs/hepta-authbus-p1-3-qualification/Cargo.toml', '[package]\nname = "codex-hepta-authbus-p1-3-qualification"\nversion = "0.0.0"\nedition = "2024"\nrust-version = "1.95"\nlicense = "Apache-2.0"\npublish = false\n\n# P1.3 is a nested, default-off qualification workspace. It centralizes quota\n# schema evidence only and does not join a product workspace or gain authority.\n[workspace]\nresolver = "3"\n\n[features]\ndefault = []\np1-3-qualification = [\n    "dep:codex-hepta-authbus-p0-3-qualification",\n    "dep:codex-hepta-authbus-qualification",\n    "dep:codex-hepta-contracts",\n    "dep:serde_json",\n]\n\n[dependencies]\ncodex-hepta-authbus-p0-3-qualification = { path = "../hepta-authbus-p0-3-qualification", features = ["p0-3-qualification"], optional = true }\ncodex-hepta-authbus-qualification = { path = "../hepta-authbus-qualification", features = ["sqlite-qualification"], optional = true }\ncodex-hepta-contracts = { path = "../hepta-contracts", features = ["authbus-local-qualification"], optional = true }\nserde_json = { version = "1.0.149", optional = true }\n\n[dev-dependencies]\npretty_assertions = "1.4.1"\n\n[lints.rust]\nunsafe_code = "forbid"\n\n[lints.clippy]\ndbg_macro = "deny"\ntodo = "deny"\nunimplemented = "deny"\n')
write('codex-rs/hepta-authbus-p1-3-qualification/README.md', '# AuthBus P1.3 canonical quota-registry qualification\n\nThis nested crate proves the default-off P1.3 quota-registry tranche.\n\nIt verifies that:\n\n- the canonical AuthBus quota vector has exactly six ordered dimensions;\n- one descriptor registry owns wire, SQLite, receipt and metric names;\n- P0.3 re-exports the contract-owned canonical type instead of defining a copy;\n- B4 and P0.2 five-dimensional values are explicit legacy projections;\n- missing `request_count` fails closed unless an explicit one-request-per-permit\n  migration policy is selected;\n- lossy downgrade is rejected;\n- schema and migration evidence are digest-bound;\n- no listener, provider call, OpenBao client or production authority is enabled.\n')
write('codex-rs/hepta-authbus-p1-3-qualification/src/lib.rs', '#![forbid(unsafe_code)]\n\n//! AuthBus P1.3 canonical quota-registry qualification seam.\n//!\n//! The default build exposes only immutable negative-authority constants.\n//! Registry and adapter qualification is compiled only through the explicit\n//! `p1-3-qualification` feature.\n\n/// This tranche is qualification evidence only.\npub const AUTHBUS_P1_3_QUALIFICATION_ONLY: bool = true;\n/// This tranche grants no AuthBus authority.\npub const AUTHBUS_P1_3_AUTHORITY: bool = false;\n/// This tranche grants no external-effect authority.\npub const AUTHBUS_P1_3_EFFECT_AUTHORITY: bool = false;\n/// This tranche is not a production caller.\npub const AUTHBUS_P1_3_PRODUCTION_CALLER: bool = false;\n/// This tranche is not a production writer.\npub const AUTHBUS_P1_3_PRODUCTION_WRITER: bool = false;\n/// This tranche records no operator acceptance.\npub const AUTHBUS_P1_3_OPERATOR_ACCEPTANCE: bool = false;\n/// This tranche performs no promotion.\npub const AUTHBUS_P1_3_PROMOTION: bool = false;\n/// This tranche cannot satisfy G5.\npub const AUTHBUS_P1_3_G5_ALLOWED: bool = false;\n/// This tranche cannot execute an external effect.\npub const AUTHBUS_P1_3_EXECUTE_ALLOWED: bool = false;\n\nconst _: () = {\n    assert!(AUTHBUS_P1_3_QUALIFICATION_ONLY);\n    assert!(!AUTHBUS_P1_3_AUTHORITY);\n    assert!(!AUTHBUS_P1_3_EFFECT_AUTHORITY);\n    assert!(!AUTHBUS_P1_3_PRODUCTION_CALLER);\n    assert!(!AUTHBUS_P1_3_PRODUCTION_WRITER);\n    assert!(!AUTHBUS_P1_3_OPERATOR_ACCEPTANCE);\n    assert!(!AUTHBUS_P1_3_PROMOTION);\n    assert!(!AUTHBUS_P1_3_G5_ALLOWED);\n    assert!(!AUTHBUS_P1_3_EXECUTE_ALLOWED);\n};\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n\n    #[test]\n    fn default_build_has_no_authority() {\n        assert!(AUTHBUS_P1_3_QUALIFICATION_ONLY);\n        assert!(!AUTHBUS_P1_3_AUTHORITY);\n        assert!(!AUTHBUS_P1_3_EFFECT_AUTHORITY);\n        assert!(!AUTHBUS_P1_3_PRODUCTION_CALLER);\n        assert!(!AUTHBUS_P1_3_PRODUCTION_WRITER);\n        assert!(!AUTHBUS_P1_3_OPERATOR_ACCEPTANCE);\n        assert!(!AUTHBUS_P1_3_PROMOTION);\n        assert!(!AUTHBUS_P1_3_G5_ALLOWED);\n        assert!(!AUTHBUS_P1_3_EXECUTE_ALLOWED);\n    }\n}\n')
write('codex-rs/hepta-authbus-p1-3-qualification/tests/p1_3.rs', '#![cfg(feature = "p1-3-qualification")]\n\nuse std::collections::BTreeMap;\n\nuse codex_hepta_authbus_p0_3_qualification::CanonicalQuotaVector as P03QuotaVector;\nuse codex_hepta_authbus_qualification::QualificationQuota;\nuse codex_hepta_authbus_p1_3_qualification::AUTHBUS_P1_3_AUTHORITY;\nuse codex_hepta_authbus_p1_3_qualification::AUTHBUS_P1_3_EFFECT_AUTHORITY;\nuse codex_hepta_authbus_p1_3_qualification::AUTHBUS_P1_3_EXECUTE_ALLOWED;\nuse codex_hepta_authbus_p1_3_qualification::AUTHBUS_P1_3_G5_ALLOWED;\nuse codex_hepta_authbus_p1_3_qualification::AUTHBUS_P1_3_OPERATOR_ACCEPTANCE;\nuse codex_hepta_authbus_p1_3_qualification::AUTHBUS_P1_3_PRODUCTION_CALLER;\nuse codex_hepta_authbus_p1_3_qualification::AUTHBUS_P1_3_PRODUCTION_WRITER;\nuse codex_hepta_authbus_p1_3_qualification::AUTHBUS_P1_3_PROMOTION;\nuse codex_hepta_authbus_p1_3_qualification::AUTHBUS_P1_3_QUALIFICATION_ONLY;\nuse codex_hepta_contracts::AUTHBUS_QUOTA_DIMENSIONS;\nuse codex_hepta_contracts::AUTHBUS_QUOTA_DIMENSION_COUNT;\nuse codex_hepta_contracts::AUTHBUS_QUOTA_REGISTRY_SCHEMA;\nuse codex_hepta_contracts::AUTHBUS_QUOTA_REGISTRY_SHA256;\nuse codex_hepta_contracts::CanonicalQuotaLimits;\nuse codex_hepta_contracts::CanonicalQuotaVector;\nuse codex_hepta_contracts::LegacyQuotaVectorV0;\nuse codex_hepta_contracts::LegacyRequestCountPolicy;\nuse codex_hepta_contracts::QuotaProjection;\nuse codex_hepta_contracts::QuotaProjectionError;\nuse codex_hepta_contracts::QuotaVector;\nuse codex_hepta_contracts::authbus_quota_registry_digest;\nuse codex_hepta_contracts::migrate_legacy_quota;\nuse codex_hepta_contracts::validate_authbus_quota_registry;\nuse pretty_assertions::assert_eq;\n\n#[test]\nfn authority_boundary_remains_closed() {\n    assert!(AUTHBUS_P1_3_QUALIFICATION_ONLY);\n    assert!(!AUTHBUS_P1_3_AUTHORITY);\n    assert!(!AUTHBUS_P1_3_EFFECT_AUTHORITY);\n    assert!(!AUTHBUS_P1_3_PRODUCTION_CALLER);\n    assert!(!AUTHBUS_P1_3_PRODUCTION_WRITER);\n    assert!(!AUTHBUS_P1_3_OPERATOR_ACCEPTANCE);\n    assert!(!AUTHBUS_P1_3_PROMOTION);\n    assert!(!AUTHBUS_P1_3_G5_ALLOWED);\n    assert!(!AUTHBUS_P1_3_EXECUTE_ALLOWED);\n}\n\n#[test]\nfn p0_3_scheduler_reexports_the_contract_owned_type() {\n    let p03 = P03QuotaVector::new(1, 2, 300, 1, 400, 512);\n    let contract: CanonicalQuotaVector = p03;\n    assert_eq!(contract.request_count, 1);\n    assert_eq!(\n        contract.digest(),\n        CanonicalQuotaVector::new(1, 2, 300, 1, 400, 512).digest()\n    );\n}\n\n#[test]\nfn descriptor_registry_owns_every_projection_surface() {\n    validate_authbus_quota_registry().expect("valid quota registry");\n    assert_eq!(AUTHBUS_QUOTA_DIMENSIONS.len(), AUTHBUS_QUOTA_DIMENSION_COUNT);\n    assert_eq!(AUTHBUS_QUOTA_REGISTRY_SCHEMA, "hepta.authbus.quota-registry.v1");\n    assert_eq!(\n        authbus_quota_registry_digest().as_str(),\n        AUTHBUS_QUOTA_REGISTRY_SHA256\n    );\n\n    let vector = CanonicalQuotaVector::new(1, 2, 300, 1, 400, 512);\n    assert_eq!(\n        vector.project(QuotaProjection::Wire),\n        BTreeMap::from([\n            ("concurrency", 1),\n            ("context", 512),\n            ("day_budget", 400),\n            ("request_count", 1),\n            ("rpm", 2),\n            ("tpm", 300),\n        ])\n    );\n    assert_eq!(\n        vector.project(QuotaProjection::SqliteLimit),\n        BTreeMap::from([\n            ("limit_concurrency", 1),\n            ("limit_context", 512),\n            ("limit_day_budget", 400),\n            ("limit_request_count", 1),\n            ("limit_rpm", 2),\n            ("limit_tpm", 300),\n        ])\n    );\n    assert_eq!(\n        vector.project(QuotaProjection::SqliteReserved),\n        BTreeMap::from([\n            ("reserved_concurrency", 1),\n            ("reserved_context", 512),\n            ("reserved_day_budget", 400),\n            ("reserved_request_count", 1),\n            ("reserved_rpm", 2),\n            ("reserved_tpm", 300),\n        ])\n    );\n    assert_eq!(\n        vector.project(QuotaProjection::SqliteUsed),\n        BTreeMap::from([\n            ("used_concurrency", 1),\n            ("used_context", 512),\n            ("used_day_budget", 400),\n            ("used_request_count", 1),\n            ("used_rpm", 2),\n            ("used_tpm", 300),\n        ])\n    );\n    assert_eq!(\n        vector.project(QuotaProjection::Receipt),\n        vector.project(QuotaProjection::Wire)\n    );\n    assert_eq!(\n        vector.project(QuotaProjection::Metric),\n        BTreeMap::from([\n            ("quota_concurrency", 1),\n            ("quota_context", 512),\n            ("quota_day_budget", 400),\n            ("quota_request_count", 1),\n            ("quota_rpm", 2),\n            ("quota_tpm", 300),\n        ])\n    );\n\n    let serialized = serde_json::to_value(vector).expect("serialize canonical quota");\n    assert_eq!(serialized.as_object().expect("object").len(), 6);\n    assert_eq!(serialized["request_count"], 1);\n}\n\n#[test]\nfn b4_legacy_projection_requires_an_explicit_request_count_policy() {\n    let legacy = QuotaVector::new(2, 300, 1, 400, 512);\n    assert_eq!(\n        legacy.try_into_canonical(LegacyRequestCountPolicy::RejectMissing),\n        Err(QuotaProjectionError::MissingRequestCount)\n    );\n    let canonical = legacy\n        .try_into_canonical(LegacyRequestCountPolicy::AssumeOnePerPermit)\n        .expect("explicit B4 migration");\n    assert_eq!(canonical.request_count, 1);\n    assert_eq!(QuotaVector::try_from_canonical(canonical), Ok(legacy));\n    assert_eq!(\n        QuotaVector::try_from_canonical(CanonicalQuotaVector::new(\n            2, 2, 300, 1, 400, 512\n        )),\n        Err(QuotaProjectionError::LossyLegacyDowngrade { request_count: 2 })\n    );\n}\n\n#[test]\nfn p0_2_storage_projection_requires_the_same_explicit_policy() {\n    let legacy = QualificationQuota {\n        rpm: 2,\n        tpm: 300,\n        concurrency: 1,\n        day_budget: 400,\n        context: 512,\n    };\n    assert_eq!(\n        legacy.try_into_canonical(LegacyRequestCountPolicy::RejectMissing),\n        Err(QuotaProjectionError::MissingRequestCount)\n    );\n    let canonical = legacy\n        .try_into_canonical(LegacyRequestCountPolicy::AssumeOnePerPermit)\n        .expect("explicit P0.2 migration");\n    assert_eq!(canonical.request_count, 1);\n    assert_eq!(\n        QualificationQuota::try_from_canonical(canonical),\n        Ok(legacy)\n    );\n    assert_eq!(\n        QualificationQuota::try_from_canonical(CanonicalQuotaVector::new(\n            0, 2, 300, 1, 400, 512\n        )),\n        Err(QuotaProjectionError::LossyLegacyDowngrade { request_count: 0 })\n    );\n}\n\n#[test]\nfn migration_receipt_binds_the_target_registry() {\n    let legacy = LegacyQuotaVectorV0 {\n        rpm: 2,\n        tpm: 300,\n        concurrency: 1,\n        day_budget: 400,\n        context: 512,\n    };\n    let (canonical, receipt) = migrate_legacy_quota(\n        legacy,\n        LegacyRequestCountPolicy::AssumeOnePerPermit,\n    )\n    .expect("migration");\n    assert_eq!(canonical.request_count, 1);\n    assert!(receipt.request_count_assumed);\n    assert_eq!(receipt.target_schema, AUTHBUS_QUOTA_REGISTRY_SCHEMA);\n    assert_eq!(\n        receipt.target_registry_sha256,\n        authbus_quota_registry_digest()\n    );\n}\n\n#[test]\nfn unknown_dimensions_and_arithmetic_overflow_fail_closed() {\n    let capacity = CanonicalQuotaVector::new(10, 10, 1_000, 4, 10_000, 20_000);\n    let requested = CanonicalQuotaVector::new(1, 1, 100, 1, 100, 512);\n    assert!(CanonicalQuotaLimits::known(capacity).can_hold(\n        CanonicalQuotaVector::default(),\n        CanonicalQuotaVector::default(),\n        requested\n    ));\n    assert!(!CanonicalQuotaLimits::unknown_request_count(capacity).can_hold(\n        CanonicalQuotaVector::default(),\n        CanonicalQuotaVector::default(),\n        requested\n    ));\n    assert!(\n        CanonicalQuotaVector::new(u64::MAX, 0, 0, 0, 0, 0)\n            .checked_add(CanonicalQuotaVector::new(1, 0, 0, 0, 0, 0))\n            .is_none()\n    );\n}\n')
write('docs/hepta-vnext/authbus/AUTHBUS_P1_3_DEVELOPMENT_PLAN_2026-08-29.md', '# AuthBus P1.3 canonical quota-registry development plan\n\nDate: 2026-08-29\nParent tranche: P1.2 executable-qualified durable identity and evidence replay state\nDisposition: **IMPLEMENT IN AN ISOLATED, DEFAULT-OFF QUALIFICATION TRANCHE**\n\n## 1. Problem statement\n\nThe inherited AuthBus qualification stack contains three incompatible quota\nrepresentations:\n\n1. B4 exposes a five-dimensional `QuotaVector`;\n2. P0.2 SQLite WAL exposes a second five-dimensional `QualificationQuota`;\n3. P0.3 defines a private six-dimensional `CanonicalQuotaVector` and silently\n   assigns `request_count = 1` when it upgrades B4.\n\nThat split allows wire, persistence, receipt and metric names to drift. It also\nallows `request_count` to be lost during downgrade without an explicit\ncompatibility decision.\n\n## 2. P1.3 target\n\nP1.3 establishes one contract-owned six-dimensional registry in\n`codex-hepta-contracts`:\n\n```text\nrequest_count\nrpm\ntpm\nconcurrency\nday_budget\ncontext\n```\n\nThe registry owns, in stable order:\n\n- canonical and wire keys;\n- SQLite limit, reserved and used columns;\n- durable receipt keys;\n- metric suffixes;\n- semantic units;\n- legacy-v0 presence;\n- a versioned SHA-256 schema digest.\n\n## 3. Compatibility rules\n\nThe B4 and P0.2 five-dimensional structs remain legacy compatibility values,\nnot schema authorities.\n\nMissing `request_count` has exactly two policies:\n\n```text\nRejectMissing\nAssumeOnePerPermit\n```\n\nThe default-safe policy is rejection. A migration may assume one request only\nwhen the caller explicitly selects `AssumeOnePerPermit`. Downgrade to five\ndimensions is permitted only when `request_count == 1`; every other value fails\nas a lossy downgrade.\n\n## 4. Source changes\n\n- add `quota_registry.rs` to `codex-hepta-contracts`;\n- re-export the registry, canonical vector, limits, projections and migration\n  types from `codex-hepta-contracts`;\n- remove the duplicate P0.3 canonical vector and limits definitions;\n- make P0.3 re-export the contract-owned canonical types;\n- add explicit legacy adapters to B4 and P0.2;\n- add the isolated `codex-hepta-authbus-p1-3-qualification` crate;\n- add a source verifier and exact-head hosted qualification workflow.\n\nNo product workspace membership, listener, provider adapter or OpenBao path is\nadded.\n\n## 5. Required executable gates\n\nThe exact final head must pass on non-zero hosted runners:\n\n1. source/cleanup/negative-authority verification;\n2. `codex-hepta-contracts` tests, check and strict Clippy;\n3. inherited P0.3 scheduler tests, check and strict Clippy;\n4. inherited P0.2 SQLite WAL tests, check and strict Clippy;\n5. P1.3 default-off test;\n6. P1.3 registry/adaptor matrix, all-target check and strict Clippy;\n7. digest-bound executable receipt validation.\n\n## 6. Exit criteria\n\nP1.3 closes only when:\n\n- the P0.3 source contains no local `CanonicalQuotaVector` or\n  `CanonicalQuotaLimits` struct;\n- all six projection surfaces originate from the one descriptor registry;\n- both five-dimensional adapters reject missing request count by default;\n- lossy downgrade is executable-tested;\n- all authority and product-wiring fields remain false;\n- an exact-head hosted run has non-empty steps, non-zero runners and success;\n- a two-file executable receipt commit verifies against that prior source run.\n\nP1.3 does not authorize production activation or P1.4.\n')
